"""Self-conjugate partitions vs partitions into distinct odd parts.

The transpose sigma fixes exactly the diagonal cells; on the partition side its
fixed points are the self-conjugate diagrams (lambda = lambda'). A classical
bijection identifies these with partitions of n into distinct odd parts. This
demo counts both and checks the two sequences agree.
"""
from __future__ import annotations
from typing import List, Set, Tuple


def conjugate(part: Tuple[int, ...]) -> Tuple[int, ...]:
    if not part:
        return ()
    return tuple(sum(1 for r in part if r > j) for j in range(part[0]))


def partitions(n: int) -> List[Tuple[int, ...]]:
    out: List[Tuple[int, ...]] = []

    def rec(rem: int, cap: int, cur: List[int]) -> None:
        if rem == 0:
            out.append(tuple(cur))
            return
        for k in range(min(rem, cap), 0, -1):
            cur.append(k)
            rec(rem - k, k, cur)
            cur.pop()

    rec(n, n, [])
    return out


def count_self_conjugate(n: int) -> int:
    return sum(1 for p in partitions(n) if conjugate(p) == p)


def count_distinct_odd(n: int) -> int:
    total = 0
    for p in partitions(n):
        if all(x % 2 == 1 for x in p) and len(set(p)) == len(p):
            total += 1
    return total


def main() -> None:
    print(" n  self-conjugate  distinct-odd  agree")
    for n in range(0, 21):
        a, b = count_self_conjugate(n), count_distinct_odd(n)
        print(f"{n:2}  {a:14}  {b:12}  {a == b}")


if __name__ == "__main__":
    main()

"""Cell-visit frequency under a measure-preserving toy shift.

We model a measure-preserving transformation of the unit square whose orbit
equidistributes, then confirm each of the four cells D1..D4 is visited with
asymptotic frequency 1/4, and that visiting a point and its conjugate sigma(p)
yields identical long-run statistics (statistical invisibility of conjugation).
"""
from __future__ import annotations
from math import sqrt
from typing import Dict, Optional, Tuple

Point = Tuple[float, float]
PHI1 = sqrt(2.0) - 1.0
PHI2 = sqrt(3.0) - 1.0


def shift(p: Point) -> Point:
    x, y = p
    return ((x + PHI1) % 1.0, (y + PHI2) % 1.0)


def sigma(p: Point) -> Point:
    x, y = p
    return (y, x)


def classify(p: Point) -> Optional[str]:
    x, y = p
    if x < 0.5 and y < 0.5:
        return "D1"
    if x < 0.5:
        return "D2"
    if y >= 0.5:
        return "D3"
    return "D4"


def visit_frequencies(start: Point, steps: int) -> Dict[str, float]:
    counts: Dict[str, int] = {"D1": 0, "D2": 0, "D3": 0, "D4": 0}
    p = start
    for _ in range(steps):
        c = classify(p)
        if c:
            counts[c] += 1
        p = shift(p)
    return {k: v / steps for k, v in counts.items()}


def main() -> None:
    steps = 500000
    f = visit_frequencies((0.123, 0.456), steps)
    print("orbit visit frequencies (each ~ 0.25):")
    for k in ("D1", "D2", "D3", "D4"):
        print(f"  {k}: {f[k]:.4f}")
    g = visit_frequencies(sigma((0.123, 0.456)), steps)
    print("conjugate-start orbit frequencies:")
    for k in ("D1", "D2", "D3", "D4"):
        print(f"  {k}: {g[k]:.4f}")


if __name__ == "__main__":
    main()

